// Scene 1: constellation heart intro
const hcv=$('hs'),hx=hcv.getContext('2d'),HN=120,hpts=[];
const hpt=t=>[180+16*Math.pow(Math.sin(t),3)*9.5,135-(13*Math.cos(t)-5*Math.cos(2*t)-2*Math.cos(3*t)-Math.cos(4*t))*9.5];
