// the beat: 124 bpm, kick on every beat, offbeat hats, claps on 2 and 4, a bass line and a bouncy arpeggio
function ptTone(t,f,d,type,g,lp){const o=ac.createOscillator(),v=ac.createGain();o.type=type;o.frequency.value=f;let n=o;
if(lp){const q=ac.createBiquadFilter();q.type='lowpass';q.frequency.value=lp;o.connect(q);n=q}
v.gain.setValueAtTime(g,t);v.gain.exponentialRampToValueAtTime(.0001,t+d);n.connect(v);v.connect(ptMaster);o.start(t);o.stop(t+d+.02)}
function ptKick(t){const o=ac.createOscillator(),v=ac.createGain();o.frequency.setValueAtTime(150,t);o.frequency.exponentialRampToValueAtTime(45,t+.12);
v.gain.setValueAtTime(.9,t);v.gain.exponentialRampToValueAtTime(.0001,t+.26);o.connect(v);v.connect(ptMaster);o.start(t);o.stop(t+.3)}
function ptHit(t,type,freq,d,g){const s=ac.createBufferSource(),f=ac.createBiquadFilter(),v=ac.createGain();s.buffer=ptNoise;f.type=type;f.frequency.value=freq;
v.gain.setValueAtTime(g,t);v.gain.exponentialRampToValueAtTime(.0001,t+d);s.connect(f);f.connect(v);v.connect(ptMaster);s.start(t);s.stop(t+d+.02)}
const PT_BASS=[130.8,98,110,87.3],PT_ARP=[[523.3,659.3,784],[493.9,587.3,784],[440,523.3,659.3],[440,523.3,698.5]];
function ptPlay(st,t){const i=st%16,bar=(st>>4)%4;
if(i%4===0)ptKick(t);
if(i%4===2)ptHit(t,'highpass',7000,.05,.12);
if(i===4||i===12)ptHit(t,'bandpass',1600,.14,.3);
if(i===0||i===3||i===6||i===10||i===14)ptTone(t,PT_BASS[bar],.2,'sawtooth',.2,420);
if(i%2===0)ptTone(t,PT_ARP[bar][(i/2)%3]*(i%8===6?2:1),.17,'triangle',.09)}
function ptSched(){while(ptNext<ac.currentTime+.18){ptPlay(ptStep,ptNext);ptNext+=60/124/4;ptStep++}}
function partyStart(){if(ptOn)return;
if(mt){clearInterval(mt);mt=null;$('mus').textContent='🎵 Music off'}
ac=ac||new (window.AudioContext||window.webkitAudioContext)();ac.resume();
if(!ptMaster){ptMaster=ac.createGain();ptMaster.gain.value=.55;ptMaster.connect(ac.destination)}
if(!ptNoise){ptNoise=ac.createBuffer(1,ac.sampleRate*.2,ac.sampleRate);const d=ptNoise.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1}
ptOn=true;ptStep=0;ptNext=ac.currentTime+.08;ptSched();ptTimer=setInterval(ptSched,40);
ptEl.classList.add('on');ptBtn.textContent='Stop the music ⏹';ptMsg.textContent='Dance, Archana, dance! 💃🕺';partyConfetti()}
function partyStop(){if(!ptOn)return;ptOn=false;clearInterval(ptTimer);ptTimer=null;
ptEl.classList.remove('on');ptBtn.textContent='Start party music 🎶';ptMsg.textContent='The whole zoo came to dance for you 💜'}
ptBtn.onclick=()=>ptOn?partyStop():partyStart();
$('pcon').onclick=partyConfetti;
$('ptop').onclick=()=>document.querySelector('#s9 .blk').scrollIntoView({behavior:'smooth'});
new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){partyConfetti();rain(6000)}}),{threshold:.7}).observe(ptEl);

