const kv=$('kv'),kx=kv.getContext('2d'),K={P:[],n:0,raf:0,t:null,t0:null};
const HEART=new Path2D('M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z');
const kOn=()=>$('s10').classList.contains('show');
function ksize(){const d=Math.min(2,devicePixelRatio||1);kv.width=innerWidth*d;kv.height=innerHeight*d;kx.setTransform(d,0,0,d,0,0)}
addEventListener('resize',()=>{if(kOn())ksize()});
function kcount(){K.n++;$('kc').textContent='Kisses sent: '+K.n;rep.kisses=(rep.kisses||0)+1;saveRep()}
function kemit(x,y,n,dx){dx=dx||0;for(let i=0;i<n;i++)K.P.push({x:x+(Math.random()-.5)*34,y:y+(Math.random()-.5)*10,vx:dx+(Math.random()-.5)*.7,vy:-1.1-Math.random()*1.5,s:7+Math.random()*13,l:1,d:.005+Math.random()*.006,ph:Math.random()*6,r:(Math.random()-.5)*.5,
c:['#ff5c97','#ff8fba','#ff3d8b','#ffc2dc'][Math.random()*4|0],del:i*5})}
// flying lips: a few small kiss marks plus one big one that grows as it flies toward you
function klips(x,y,dx){for(let i=0;i<3;i++)K.P.push({x:x,y:y,vx:dx+(Math.random()-.3)*.9,vy:-.9-Math.random(),s:22+Math.random()*12,l:1,d:.006+Math.random()*.004,ph:Math.random()*6,r:(Math.random()-.5)*.8,c:'#ff3d8b',e:'💋',del:i*10});
K.P.push({x:x,y:y,vx:dx*.5,vy:-.7,s:20,l:1,d:.008,ph:0,r:-.2,c:'#ff3d8b',e:'💋',g:1,del:6})}
function kloop(){if(!kOn()){K.raf=0;kv.style.display='none';return}
K.raf=requestAnimationFrame(kloop);kx.clearRect(0,0,innerWidth,innerHeight);
K.P=K.P.filter(p=>{if(p.del>0){p.del--;return true}p.y+=p.vy;p.x+=p.vx+Math.sin(p.l*9+p.ph)*.5;p.vy*=.998;p.l-=p.d;if(p.l<=0)return false;
kx.save();kx.translate(p.x,p.y);kx.rotate(p.r+Math.sin(p.l*6+p.ph)*.2);kx.globalAlpha=Math.min(1,p.l*2.2)*.9;kx.fillStyle=p.c;kx.shadowColor=p.c;kx.shadowBlur=10;
if(p.e){kx.shadowBlur=6;kx.font=Math.round(p.s)+'px serif';kx.textAlign='center';kx.textBaseline='middle';kx.fillText(p.e,0,0);if(p.g)p.s+=.7}else{kx.scale(p.s/24,p.s/24);kx.translate(-12,-12);kx.fill(HEART)}kx.restore();return true})}
// one kiss: she blows a flying kiss and hearts fly off her hand (or rise from the spot you tapped)
function kiss(x,y){if(!kOn())return;const h=$('kh');
h.classList.remove('blow');void h.getBoundingClientRect();h.classList.add('blow');
if(x==null){setTimeout(()=>{if(!kOn())return;const r=h.getBoundingClientRect();kemit(r.left+r.width*.84,r.top+r.height*.5,8,1.2);klips(r.left+r.width*.84,r.top+r.height*.5,1.2)},520)}
else{kemit(x,y,6,0);klips(x,y,0)}
kcount();try{navigator.vibrate&&navigator.vibrate(12)}catch(e){}}
function startKiss(){$('rain').innerHTML='';ksize();kv.style.display='block';K.P=[];K.n=0;$('kc').textContent='Kisses sent: 0';
clearInterval(K.t);clearTimeout(K.t0);
$('kh').classList.remove('blow');
if(!K.raf)K.raf=requestAnimationFrame(kloop);
K.t0=setTimeout(()=>{kiss();K.t=setInterval(()=>{if(!kOn()){clearInterval(K.t);return}kiss()},2600)},1400)}
$('kmore').onclick=()=>{for(let i=0;i<3;i++)setTimeout(()=>kiss(),i*220)};
