// ===== Report (only sent when she taps a send button; each button says what it sends) =====
const rp=store('rep')||{};const rep={game:rp.game||'',date:rp.date||'',coupons:rp.coupons||[],wishes:rp.wishes||[],scores:rp.scores||{},kisses:rp.kisses||0};const saveRep=()=>store('rep',rep);
// Mail transport. The settings (MAIL) are at the very top of this file.
// Delivery order: Web3Forms (only if a key is set) -> FormSubmit. If one fails the next is tried.
// fetch with a 15 second timeout so a stuck network never leaves "Sending…" on screen forever
async function post(url,payload){const ac2=new AbortController(),t=setTimeout(()=>ac2.abort(),15000);
try{const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(payload),signal:ac2.signal});
let d={};try{d=await r.json()}catch(e){}return{r:r,d:d}}
catch(e){throw new Error(e&&e.name==='AbortError'?'timeout':'network: '+(e&&e.message||'blocked'))}
finally{clearTimeout(t)}}
async function viaWeb3(subject,data){const x=await post('https://api.web3forms.com/submit',Object.assign({access_key:MAIL.web3,subject:subject,from_name:'Archana'},data));
if(!x.r.ok||String(x.d.success)!=='true')throw new Error('web3forms: '+(x.d.message||'failed ('+x.r.status+')'))}
async function viaFormSubmit(subject,data){const x=await post('https://formsubmit.co/ajax/'+MAIL.to,Object.assign({_subject:subject,_captcha:'false',_template:'table',name:'Archana'},data));
const m=String(x.d.message||'');
// an "activate" reply means nothing was delivered yet, even if the service also says success
if(/activat/i.test(m))throw new Error('formsubmit: needs activation. '+m);
if(!x.r.ok||String(x.d.success)!=='true')throw new Error('formsubmit: '+(m||'failed ('+x.r.status+')'))}
// one retry on a flaky connection (timeout / network); never retry a rejection from the service itself
async function withRetry(fn){for(let a=0;;a++){try{return await fn()}catch(e){const m=String(e&&e.message||'');if(a>=1||!/^(timeout|network)/.test(m))throw e;await new Promise(r=>setTimeout(r,1500))}}}
// fields = one labelled row per item, so the email reads as a clean table instead of one long blob
// resolves with the name of the service that delivered it
async function deliver(subject,body,fields){
const data=fields||{message:body},tries=[],errs=[];
if(MAIL.web3)tries.push(['web3forms',()=>viaWeb3(subject,data)]);
tries.push(['formsubmit',()=>viaFormSubmit(subject,data)]);
for(const t of tries){try{await withRetry(t[1]);return t[0]}catch(e){const m=String(e&&e.message||e);errs.push(m);
// the service answered but refused the detailed table: retry once as one plain message
if(/^(formsubmit|web3forms): /.test(m)&&!/activat/i.test(m)&&fields){try{await withRetry(()=>t[0]==='web3forms'?viaWeb3(subject,{message:body}):viaFormSubmit(subject,{message:body}));return t[0]}catch(e2){errs.push('plain retry: '+String(e2&&e2.message||e2))}}}}
throw new Error((location.protocol==='file:'?'file: ':'')+errs.join(' | '))}
// Outbox: a message that could not be delivered is kept on this device and retried by itself
const outbox=()=>store('outbox')||[];
function queueMsg(subject,body,fields){const q=outbox();q.push({id:Date.now()+'-'+Math.random().toString(36).slice(2,7),subject:subject,body:body,fields:fields});store('outbox',q.slice(-6))}
let flushing=false;
async function flushOutbox(quiet){if(flushing||location.protocol==='file:'||!outbox().length)return false;flushing=true;let n=0;
try{for(const m of outbox()){await deliver(m.subject,m.body,m.fields);store('outbox',outbox().filter(x=>x.id!==m.id));n++}}
catch(e){console.warn('outbox retry failed:',e&&e.message)}
finally{flushing=false}
if(n&&!quiet)toast('Your earlier message was delivered 💖');return n>0}
addEventListener('online',()=>flushOutbox());
setTimeout(()=>flushOutbox(true),3000);
function mailFallback(st,queued,subject,body,why){st.textContent=(queued?'Could not send it right now. It is saved on this device and will retry by itself. Or send it by email: ':'Could not send it automatically. Send it by email instead: ')+(why?' [reason: '+why+']':'');
const a=el('button','Open email app','ghost pill mfb',st),b=el('button','Copy message','ghost pill mfb',st);
a.onclick=()=>{location.href='mailto:'+MAIL.to+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body.slice(0,1800))};
b.onclick=async()=>{try{await navigator.clipboard.writeText(body);toast('Copied. Paste it into a message to '+MAIL.to)}catch(e){toast('Copy did not work. Long-press the text to copy.')}}}
async function sendReport(keys,st,note,btn){
const V={note:()=>['Her note',note||'(none)'],
date:()=>['Date pick',rep.date||'not chosen yet'],
game:()=>['Catch-the-hearts game',rep.game||'not played yet'],
coupons:()=>['Coupons redeemed',rep.coupons.length?rep.coupons.join(', '):'none yet'],
games:()=>['Game zone best scores',Object.keys(rep.scores).length?Object.entries(rep.scores).map(e=>e[0]+' '+e[1]).join(', '):'none yet'],
wishes:()=>['Wishes',rep.wishes.length?rep.wishes.join(' | '):'none yet'],
gifts:()=>{const d=gdone();return ['Gifts opened',(d.length?GFT.filter(g=>d.includes(g.id)).map(g=>g.t).join(', '):'none yet')+(store('gfin')?' (and the last gift)':'')]},
kisses:()=>['Kisses sent',String(rep.kisses||0)]};
const rows=keys.map(k=>V[k]()),sent=new Date().toLocaleString();
const body=['From Archana’s surprise page 💖','Sent: '+sent,''].concat(rows.map(r=>r[0]+': '+r[1])).join('\n'),subject='Archana sent you something';
const fields={};rows.forEach(r=>{fields[r[0]]=r[1]});fields['Sent at']=sent;fields.message=body;
if(btn)btn.disabled=true;st.textContent='Sending…';
try{await deliver(subject,body,fields);st.textContent='Sent 💖 He will read it soon.';toast('Sent 💖');flushOutbox(true)}
catch(e){const m=String(e&&e.message||'');console.warn('mail failed:',m);const q=!/^file/.test(m);if(q)queueMsg(subject,body,fields);mailFallback(st,q,subject,body,m.slice(0,120))}
finally{if(btn)setTimeout(()=>{btn.disabled=false},2500)}}
// For him: send yourself a test from the Options panel before giving her the link
async function testMail(btn){btn.disabled=true;const out=$('o-mst'),say=t=>{if(out)out.textContent=t;toast(t,6000)};say('Sending test…');
try{const via=await deliver('Test from Archana’s page','If you can read this, the mail system works 💖',{Test:'If you can read this, the mail system works 💖','Sent at':new Date().toLocaleString()});
say('Sent via '+(via==='web3forms'?'Web3Forms':'FormSubmit')+'. Now check '+MAIL.to+' (Inbox, Spam and Promotions).'+(via==='formsubmit'?' If nothing arrives within a minute, open the email from FormSubmit, tap Activate, then test again.':''));flushOutbox(true)}
catch(e){const m=String(e&&e.message||'');console.warn('test mail failed:',m);
say(/activat/i.test(m)?'FormSubmit sent an activation email to '+MAIL.to+'. Open it (check Spam and Promotions), tap Activate, then test again.':/^file/.test(m)?'This page was opened as a file, so the browser blocked the request. Put it on a website (Netlify, GitHub Pages…) and test from that link.':/timeout|network/.test(m)?'Could not reach the mail service. Check the internet, turn off ad blockers or VPN for this page, then test again.':'Could not send ('+m.slice(0,140)+').')}
finally{btn.disabled=false}}
